 {juce::AudioBuffer<float> exported(2,48000);for(int ch=0;ch<2;++ch)exported.copyFrom(ch,0,data->buffer,ch,0,48000);if(!renderTrackStemMix(exported,48000,{1,1,1,1}))return 1822;for(int ch=0;ch<2;++ch)for(int n=0;n<48000;++n)if(std::abs(exported.getSample(ch,n)-data->buffer.getSample(ch,n))>1e-6)return 1823;if(!renderTrackStemMix(exported,48000,{0,0,0,0})||exported.getMagnitude(0,48000)>1e-8)return 1824;}
