 {juce::AudioBuffer<float> partial(data->buffer);int begin=286650,end=291060;if(!renderTrackStemMix(partial,44100,{0,0,0,1},{},begin,end))return 1854;for(int ch=0;ch<2;++ch){for(int n=begin;n<end;++n){std::array<float,4> values;if(!w->read(n,ch,values)||std::abs(partial.getSample(ch,n)-values[3])>1e-5)return 1855;}if(partial.getSample(ch,begin-1)!=data->buffer.getSample(ch,begin-1)||partial.getSample(ch,end)!=data->buffer.getSample(ch,end))return 1856;}}
